-- CLASS_MIGRATION_SCOPE: mechanics
-- CLASS_INTEGRATION_STRICT: class:wizard
-- CLASS_PACKAGE_TEST: tests/wizardSubclassRuntime.test.ts
-- CLASS_RESOURCE_POLICY: short-long-rest-v1
-- CLASS_WORK_STATUS: wizard:text=READY;mechanics=READY
-- CLASS_STATUS_LEDGER: src/rule-templates/CLASS_WORK_STATUS.md
-- Generated from src/rule-templates/wizardSubclassMechanics.ts.

begin;

create or replace function private.upsert_wizard_subclass_runtime_v3(
  p_campaign_id uuid,
  p_parent_template_id uuid,
  p_slug text,
  p_catalog_key text,
  p_name text,
  p_description text,
  p_mechanical_summary text,
  p_source_label text,
  p_rules_revision text,
  p_level_3 jsonb,
  p_choices_3 jsonb,
  p_level_6 jsonb,
  p_choices_6 jsonb,
  p_level_10 jsonb,
  p_choices_10 jsonb,
  p_level_14 jsonb,
  p_choices_14 jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_template uuid;
begin
  select id into v_template
  from public.rule_templates
  where campaign_id=p_campaign_id
    and kind='subclass'
    and catalog_key=p_catalog_key
    and is_builtin is true
  order by is_active desc, version desc, created_at desc
  limit 1;

  if v_template is null then
    insert into public.rule_templates(
      campaign_id,kind,slug,name,description,version,mechanics,choices,parent_template_id,unlock_level,
      catalog_key,catalog_revision,source_kind,source_label,is_builtin,mechanical_summary,
      author_description,author_comment,rules_meta,created_by,is_active
    ) values (
      p_campaign_id,'subclass',p_slug,p_name,p_description,1,'[]'::jsonb,'[]'::jsonb,p_parent_template_id,3,
      p_catalog_key,'wizard-subclasses-runtime@3','official',p_source_label,true,p_mechanical_summary,
      '','',jsonb_build_object(
        'base_class','class:wizard',
        'rules_revision',p_rules_revision,
        'mechanics_status','READY',
        'feature_levels',jsonb_build_array(3,6,10,14),
        'chat_template_actions',true,
        'chat_template_spells',true
      ),null,true
    ) returning id into v_template;
  else
    update public.rule_templates
    set slug=p_slug,
        name=p_name,
        description=p_description,
        mechanics='[]'::jsonb,
        choices='[]'::jsonb,
        parent_template_id=p_parent_template_id,
        unlock_level=3,
        catalog_revision='wizard-subclasses-runtime@3',
        source_kind='official',
        source_label=p_source_label,
        is_builtin=true,
        mechanical_summary=p_mechanical_summary,
        author_description='',
        author_comment='',
        rules_meta=jsonb_build_object(
          'base_class','class:wizard',
          'rules_revision',p_rules_revision,
          'mechanics_status','READY',
          'feature_levels',jsonb_build_array(3,6,10,14),
          'chat_template_actions',true,
          'chat_template_spells',true
        ),
        is_active=true,
        updated_at=now()
    where id=v_template;
  end if;

  delete from public.rule_template_levels where template_id=v_template;
  insert into public.rule_template_levels(template_id,level,mechanics,choices) values
    (v_template,3,p_level_3,p_choices_3),
    (v_template,6,p_level_6,p_choices_6),
    (v_template,10,p_level_10,p_choices_10),
    (v_template,14,p_level_14,p_choices_14);
end;
$function$;

create or replace function private.install_wizard_subclass_runtime_v3(p_campaign_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_wizard uuid;
begin
  perform private.install_wizard_2024_text_pack(p_campaign_id);
  perform private.install_wizard_2024_mechanics_v1(p_campaign_id);

  select id into v_wizard
  from public.rule_templates
  where campaign_id=p_campaign_id
    and kind='class'
    and catalog_key='class:wizard'
    and is_builtin is true
  order by is_active desc, version desc, created_at desc
  limit 1;
  if v_wizard is null then raise exception 'Built-in Wizard was not installed'; end if;

  update public.rule_templates
  set rules_meta=coalesce(rules_meta,'{}'::jsonb)||jsonb_build_object(
        'subclasses_included',true,
        'subclass_supported_count',13,
        'subclass_mechanics_status','READY',
        'subclass_runtime_revision','wizard-subclasses-runtime@3'
      ),
      updated_at=now()
  where id=v_wizard;

  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-abjurer', 'subclass:wizard:abjurer', 'Абьюратор',
    'Абьюратор превращает Ограждение в рабочую защиту: книгу защитных заклинаний, Тайный заслон, защиту союзника и инструменты против чужих чар.', 'Тайный заслон хранит HP и факт создания до долгого отдыха; ситуативные боевые триггеры остаются на решении ГМ.',
    'Player''s Handbook 2024', 'phb-2024',
    '[{"id":"abjurer-savant-rules","type":"grant","sourceKey":"wizard:abjurer:savant","target":"feature","key":"subclass:wizard:abjurer:savant","payload":{"label":"Знаток Ограждения","description":"При получении подкласса добавьте в книгу два заклинания Волшебника школы Ограждения не выше 2 уровня. Каждый раз, когда Волшебник впервые получает ячейки нового уровня, добавьте ещё одно заклинание Волшебника этой школы доступного уровня. Эти заклинания не занимают обычные два заклинания за уровень.","mechanic":{"kind":"wizard_school_savant","school":"abjuration","addsToSpellbook":true,"initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}}},{"id":"abjurer-savant-permission","type":"grant","sourceKey":"wizard:abjurer:savant","target":"permission","key":"wizard.school_savant.abjuration","payload":{"label":"Бесплатные заклинания: Ограждения","school":"abjuration","destination":"spellbook","initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}},{"id":"abjurer-arcane-ward-hp","type":"resource","sourceKey":"wizard:abjurer:arcane-ward","key":"wizard_abjurer_arcane_ward","label":"HP Тайного заслона","max":{"kind":"add","terms":[{"kind":"multiply","factors":[{"kind":"literal","value":2},{"kind":"reference","key":"source.level"}]},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"abjurer-arcane-ward-rules","type":"grant","sourceKey":"wizard:abjurer:arcane-ward","target":"feature","key":"subclass:wizard:abjurer:arcane-ward","payload":{"label":"Тайный заслон","description":"Когда вы впервые после долгого отдыха накладываете заклинание Ограждения ячейкой, создайте Тайный заслон с максимумом HP, равным удвоенному уровню Волшебника + модификатор Интеллекта. Заслон существует до долгого отдыха даже при 0 HP. При каждом заклинании Ограждения, наложенном ячейкой, восстановите HP заслона на удвоенный уровень ячейки. Бонусным действием можно потратить ячейку и восстановить столько же HP.","mechanic":{"kind":"damage_buffer","resource":"wizard_abjurer_arcane_ward","createdState":"recovery-state[long_rest]::wizard_abjurer_arcane_ward_created","maximum":"2 * wizard_level + intelligence_modifier","restoreOnAbjurationSlotCast":"2 * slot_level","bonusActionSlotRestore":true}}},{"id":"abjurer-ward-cast-restore-1","type":"action","sourceKey":"wizard:abjurer:arcane-ward","key":"abjurer_ward_cast_restore_1","label":"Учесть Ограждение ячейкой 1 уровня","economy":"special","effects":[{"kind":"state","key":"recovery-state[long_rest]::wizard_abjurer_arcane_ward_created","operation":"SET","value":true},{"kind":"resource","key":"wizard_abjurer_arcane_ward","operation":"RESTORE","amount":2},{"kind":"semantic","key":"arcane_ward_abjuration_cast","payload":{"slotLevel":1,"createsWardIfAbsent":true}}],"tags":["wizard","subclass","gm-adjudicated-trigger","slot:1"]},{"id":"abjurer-ward-cast-restore-2","type":"action","sourceKey":"wizard:abjurer:arcane-ward","key":"abjurer_ward_cast_restore_2","label":"Учесть Ограждение ячейкой 2 уровня","economy":"special","effects":[{"kind":"state","key":"recovery-state[long_rest]::wizard_abjurer_arcane_ward_created","operation":"SET","value":true},{"kind":"resource","key":"wizard_abjurer_arcane_ward","operation":"RESTORE","amount":4},{"kind":"semantic","key":"arcane_ward_abjuration_cast","payload":{"slotLevel":2,"createsWardIfAbsent":true}}],"tags":["wizard","subclass","gm-adjudicated-trigger","slot:2"]},{"id":"abjurer-ward-cast-restore-3","type":"action","sourceKey":"wizard:abjurer:arcane-ward","key":"abjurer_ward_cast_restore_3","label":"Учесть Ограждение ячейкой 3 уровня","economy":"special","effects":[{"kind":"state","key":"recovery-state[long_rest]::wizard_abjurer_arcane_ward_created","operation":"SET","value":true},{"kind":"resource","key":"wizard_abjurer_arcane_ward","operation":"RESTORE","amount":6},{"kind":"semantic","key":"arcane_ward_abjuration_cast","paylo