    '[{"id":"abjurer-projected-ward-rules","type":"grant","sourceKey":"wizard:abjurer:projected-ward","target":"feature","key":"subclass:wizard:abjurer:projected-ward","payload":{"label":"Переданный заслон","description":"Когда видимое существо в пределах 30 футов получает урон, реакцией направьте на него созданный Тайный заслон. Урон уменьшает HP заслона; остаток получает защищаемое существо. Приложение не проверяет видимость, дистанцию или момент получения урона — это решает ГМ.","mechanic":{"kind":"reaction_damage_buffer","resource":"wizard_abjurer_arcane_ward","rangeFeet":30,"usesReaction":true}}},{"id":"abjurer-projected-ward-action","type":"action","sourceKey":"wizard:abjurer:projected-ward","key":"wizard_abjurer_projected_ward","label":"Передать Тайный заслон","economy":"reaction","range":{"kind":"ranged","normal":30,"unit":"ft"},"requirements":[{"kind":"condition","condition":{"kind":"state","key":"recovery-state[long_rest]::wizard_abjurer_arcane_ward_created","operator":"EQUALS","value":true},"label":"Тайный заслон создан"},{"kind":"resource","key":"wizard_abjurer_arcane_ward","minimum":1,"label":"У заслона есть HP"}],"effects":[{"kind":"semantic","key":"damage_buffer_redirect","payload":{"resource":"wizard_abjurer_arcane_ward","rangeFeet":30}}],"tags":["wizard","subclass","reaction","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"abjurer-spell-breaker-rules","type":"grant","sourceKey":"wizard:abjurer:spell-breaker","target":"feature","key":"subclass:wizard:abjurer:spell-breaker","payload":{"label":"Разрушитель чар","description":"Контрзаклинание и Рассеивание магии всегда подготовлены и не занимают лимит подготовки. Рассеивание магии можно накладывать бонусным действием. Если Контрзаклинание или Рассеивание магии, наложенное ячейкой, не прекращает заклинание, ячейка не расходуется. ГМ определяет, когда условие выполнено; кнопка только возвращает соответствующую ячейку.","mechanic":{"kind":"spell_breaker","alwaysPrepared":["counterspell","dispel-magic"],"dispelMagicBonusAction":true,"addProficiencyToDispelCheck":true,"refundSlotOnFailedBreak":true}}},{"id":"abjurer-counterspell-access","type":"spell","sourceKey":"wizard:abjurer:spell-breaker","key":"spell:counterspell","catalogSlug":"counterspell","variantKey":"wizard:abjurer:spell-breaker:counterspell","payload":{"spell":{"name":"Контрзаклинание","level":3,"school":"abjuration"},"preparation":{"mode":"always_prepared"},"methods":[{"key":"reaction","kind":"class_spell","ability":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"attackBonus":{"kind":"add","terms":[{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"requiresPrepared":false,"resourceOptions":[{"key":"slot-3","castLevel":3,"label":"Ячейка 3 уровня","costs":[{"key":"spell_slot_3","amount":1}]},{"key":"slot-4","castLevel":4,"label":"Ячейка 4 уровня","costs":[{"key":"spell_slot_4","amount":1}]},{"key":"slot-5","castLevel":5,"label":"Ячейка 5 уровня","costs":[{"key":"spell_slot_5","amount":1}]},{"key":"slot-6","castLevel":6,"label":"Ячейка 6 уровня","costs":[{"key":"spell_slot_6","amount":1}]},{"key":"slot-7","castLevel":7,"label":"Ячейка 7 уровня","costs":[{"key":"spell