  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-evoker', 'subclass:wizard:evoker', 'Воплотитель',
    'Воплотитель усиливает прямой урон и хранит только то состояние, которое переживает конкретный бросок: безопасную Перегрузку и число повторных Перегрузок до отдыха.', 'Разовые боевые условия не становятся ресурсами; Перегрузка хранит безопасное использование и растущий счётчик отдачи до долгого отдыха.',
    'Player''s Handbook 2024', 'phb-2024',
    '[{"id":"evoker-savant-rules","type":"grant","sourceKey":"wizard:evoker:savant","target":"feature","key":"subclass:wizard:evoker:savant","payload":{"label":"Знаток Воплощения","description":"При получении подкласса добавьте в книгу два заклинания Волшебника школы Воплощения не выше 2 уровня. Каждый раз, когда Волшебник впервые получает ячейки нового уровня, добавьте ещё одно заклинание Волшебника этой школы доступного уровня. Эти заклинания не занимают обычные два заклинания за уровень.","mechanic":{"kind":"wizard_school_savant","school":"evocation","addsToSpellbook":true,"initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}}},{"id":"evoker-savant-permission","type":"grant","sourceKey":"wizard:evoker:savant","target":"permission","key":"wizard.school_savant.evocation","payload":{"label":"Бесплатные заклинания: Воплощения","school":"evocation","destination":"spellbook","initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}},{"id":"evoker-potent-cantrip-rules","type":"grant","sourceKey":"wizard:evoker:potent-cantrip","target":"feature","key":"subclass:wizard:evoker:potent-cantrip","payload":{"label":"Мощный заговор","description":"Если наносящий урон заговор Волшебника промахивается атакой заклинанием или цель успешно проходит его спасбросок, цель всё равно получает половину урона заговора без дополнительных эффектов этого попадания. Это правило не создаёт ресурс.","mechanic":{"kind":"potent_cantrip","appliesTo":"wizard_cantrip_damage","missOrSuccessfulSave":"half_damage","noAdditionalEffects":true}}}]'::jsonb, '[]'::jsonb,
    '[{"id":"evoker-sculpt-spells-rules","type":"grant","sourceKey":"wizard:evoker:sculpt-spells","target":"feature","key":"subclass:wizard:evoker:sculpt-spells","payload":{"label":"Ваяние заклинаний","description":"При сотворении заклинания Воплощения выберите до 1 + уровень заклинания видимых существ в его области. Они автоматически успешно проходят спасброски против этого заклинания и не получают урон, который при успехе обычно был бы половинным. Выбор действует только для этого заклинания и не сохраняется как ресурс.","mechanic":{"kind":"sculpt_spells","school":"evocation","protectedCreaturesFormula":"1 + spell_level","autoSaveSuccess":true,"negatesHalfDamageOnSuccessfulSave":true}}}]'::jsonb, '[]'::jsonb,
    '[{"id":"evoker-empowered-evocation-rules","type":"grant","sourceKey":"wizard:evoker:empowered-evocation","target":"feature","key":"subclass:wizard:evoker:empowered-evocation","payload":{"label":"Усиленное воплощение","description":"При сотворении заклинания Волшебника школы Воплощения добавьте модификатор Интеллекта к одному броску его урона. Ограничение «один раз на заклинание» не создаёт отдельный ресурс.","mechanic":{"kind":"spell_damage_modifier","appliesTo":"wizard_evocation_spell","modifier":"intelligence_modifier","oncePerSpell":true}}}]'::jsonb, '[]'::jsonb,
    '[{"id":"evoker-overchannel-safe-use","type":"resource","sourceKey":"wizard:evoker:overchannel","key":"wizard_evoker_overchannel_safe","label":"Безопасная перегрузка","max":1,"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"evoker-overchannel-rules","type":"grant","sourceKey":"wizard:evoker:overchannel","target":"feature","key":"subclass:wizard:evoker:overchannel","payload":{"label":"Перегрузка","description":"При сотворении наносящего урон заклинания Волшебника ячейкой 1–5 уровня можно назначить максимальный урон вместо броска в ход сотворения. Первое использование после долгого отдыха безопасно. При каждом повторном использовании до следующего долгого отдыха вы получаете некротическую отдачу: 2d12 за уровень ячейки при первом повторе и ещё +1d12 за уровень ячейки за каждый следующий повтор. Число повторов хранится до долгого отдыха.","mechanic":{"kind":"overchannel","resource":"wizard_evoker_overchannel_safe","repeatState":"recovery-state[long_rest]::wizard_evoker_overchannel_repeat_count","spellSlotMin":1,"spellSlotMax":5,"maximizeDamageThisTurn":true,"repeatNecroticBacklash":{"dicePerSlotLevel":"repeat_count + 1","ignoresResistanceAndImmunity":true}}}},{"id":"evoker-overchannel-safe-action","type":"action","sourceKey":"wizard:evoker:overchannel","key":"wizard_evoker_overchannel_safe","label":"Перегрузить заклинание без отдачи","economy":"special","resourceCosts":[{"key":"wizard_evoker_overchannel_safe","amount":1}],"effects":[{"kind":"state","key":"recovery-state[long_rest]::wizard_evoker_overchannel_repeat_count","operation":"SET","value":0},{"kind":"semantic","key":"maximize_spell_damage","payload":{"slotMin":1,"slotMax":5}}]},{"id":"evoker-overchannel-repeat-action","type":"action","sourceKey":"wizard:evoker:overchannel","key":"wizard_evoker_overchannel_repeat","label":"Повторно перегрузить заклинание","economy":"special","requirements":[{"kind":"condition","condition":{"kind":"state","key":"recovery-state[long_rest]::wizard_evoker_overchannel_repeat_count","operator":"EXISTS"},"label":"Сначала используйте безопасную Перегрузку после продолжительного отдыха"}],"effects":[{"kind":"state","key":"recovery-state[long_rest]::wizard_evoker_overchannel_repeat_count","operation":"ADD","value":1},{"kind":"semantic","key":"overchannel_repeat","payload":{"slotMin":1,"slotMax":5,"counterState":"recovery-state[long_rest]::wizard_evoker_overchannel_repeat_count","backlashDicePerSlotLevel":"repeat_count + 1","damageType":"necrotic","ignoresResistanceAndImmunity":true}}],"tags":["wizard","subclass","persistent-counter"]}]'::jsonb, '[]'::jsonb
  );

  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-illusionist', 'subclass:wizard:illusionist', 'Иллюзионист',
    'Иллюзионист хранит только реальные ограниченные применения: два бесплатных призыва и Иллюзорное я. Ситуативные условия Иллюзорной реальности остаются ГМу.', 'Бесплатные призывы и Иллюзорное я — ресурсы; разовые условия попадания, дистанции и существования иллюзии не становятся состоянием CE.',
    'Player''s Handbook 2024', 'phb-2024',
    '[{"id":"illusionist-savant-rules","type":"grant","sourceKey":"wizard:illusionist:savant","target":"feature","key":"subclass:wizard:illusionist:savant","payload":{"label":"Знаток Иллюзии","description":"При получении подкласса добавьте в книгу два заклинания Волшебника школы Иллюзии не выше 2 уровня. Каждый раз, когда Волшебник впервые получает ячейки нового уровня, добавьте ещё одно заклинание Волшебника этой школы доступного уровня. Эти заклинания не занимают обычные два заклинания за уровень.","mechanic":{"kind":"wizard_school_savant","school":"illusion","addsToSpellbook":true,"initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}}},{"id":"illusionist-savant-permission","type":"grant","sourceKey":"wizard:illusionist:savant","target":"permission","key":"wizard.school_savant.illusion","payload":{"label":"Бесплатные заклинания: Иллюзии","school":"illusion","destination":"spellbook","initialSpells":2,"initialMaxSpellLevel":2,"additionalSpellOnNewSlotLevel":1}},{"id":"illusionist-improved-illusions-rules","type":"grant","sourceKey":"wizard:illusionist:improved-illusions","target":"feature","key":"subclass:wizard:illusionist:improved-illusions","payload":{"label":"Улучшенные иллюзии","description":"Заклинания Иллюзии можно накладывать без словесных компонентов. Их дальность увеличивается на 60 футов, если базовая дальность не меньше 10 футов. Вы знаете Малую иллюзию сверх лимита заговоров; она может одновременно создавать звук и изображение и может накладываться бонусным действием.","mechanic":{"kind":"improved_illusions","removeVerbalComponentsFromIllusionSpells":true,"rangeBonusFeet":60,"minorIllusion":{"granted":true,"soundAndImageTogether":true,"canCastAsBonusAction":true}}}},{"id":"illusionist-minor-illusion-access","type":"spell","sourceKey":"wizard:illusionist:improved-illusions","key":"spell:minor-illusion","catalogSlug":"minor-illusion","variantKey":"wizard:illusionist:improved-illusions:minor-illusion","payload":{"spell":{"name":"Малая иллюзия","level":0,"school":"illusion"},"preparation":{"mode":"not_required"},"methods":[{"key":"cantrip","kind":"class_spell","ability":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"requiresPrepared":false}]}}]'::jsonb, '[]'::jsonb,
    '[{"id":"illusionist-free-summon-beast-resource","type":"resource","sourceKey":"wizard:illusionist:phantasmal-creatures","key":"wizard_illusionist_free_summon_beast","label":"Призрачный зверь без ячейки","max":1,"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"illusionist-free-summon-fey-resource","type":"resource","sourceKey":"wizard:illusionist:phantasmal-creatures","key":"wizard_illusionist_free_summon_fey","label":"Призрачная фея без ячейки","max":1,"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"illusionist-phantasmal-creatures-rules","type":"grant","sourceKey":"wizard:illusionist:phantasmal-creatures","target":"feature","key":"subclass:wizard:illusionist:phantasmal-creatures","payload":{"label":"Фантомные существа","description":"Призыв зверя и Призыв феи всегда подготовлены. Каждое из них можно один раз до долгого отдыха наложить без ячейки; существо такого бесплатного призыва имеет половину обычных HP. Эти два бесплатных применения хранятся раздельно.","mechanic":{"kind":"phantasmal_creatures","alwaysPrepared":["summon-beast","summon-fey"],"canTreatAsIllusion":true,"freeCastEachPerLongRest":true,"freeCastSummonHpMultiplier":0.5}}},{"id":"illusionist-summon-beast-access","type":"spell","sourceKey":"wizard:illusionist:phantasmal-creatures","key":"spell:summon-beast","catalogSlug":"summon-beast","variantKey":"wizard:illusionist:phantasmal-creatures:summon-beast","payload":{"spell":{"name":"Призыв зверя","level":2,"school":"conjuration"},"preparation":{"mode":"always_prepared"},"methods":[{"key":"slot","kind":"class_spell","ability":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"attackBonus":{"kind":"add","terms":[{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","k