  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-enchantment', 'subclass:wizard:enchantment', 'Школа очарования',
    'Очарователь вмешивается в волю и память; приложение показывает действия, а цели, дистанции, иммунитеты и длительность контролирует ГМ.', 'У подкласса нет конечного пула: все ограничения зависят от сцены или конкретной цели и остаются в ведении ГМ.',
    'Player''s Handbook 2014', '2014-compatible-on-wizard-2024',
    '[{"id":"enchantment-legacy-savant-rules","type":"grant","sourceKey":"wizard:enchantment:savant","target":"feature","key":"subclass:wizard:enchantment:savant","payload":{"label":"Знаток Очарования","description":"Время и золото, необходимые для переписывания заклинания школы Очарования в книгу заклинаний, уменьшаются вдвое. Эту транзакцию подтверждает ГМ.","mechanic":{"kind":"wizard_legacy_school_savant","school":"enchantment","copyTimeMultiplier":0.5,"copyGoldMultiplier":0.5}}},{"id":"enchantment-hypnotic-gaze-rules","type":"grant","sourceKey":"wizard:enchantment:hypnotic-gaze","target":"feature","key":"subclass:wizard:enchantment:hypnotic-gaze","payload":{"label":"Гипнотический взгляд","description":"Действием выберите видимое существо в 5 футах, способное видеть или слышать вас. При провале спасброска Мудрости против Сл заклинаний оно очаровано, недееспособно и имеет скорость 0 до конца вашего следующего хода; действие продлевает эффект. Дистанцию, урон, чувства и иммунитет цели до долгого отдыха отслеживает ГМ.","mechanic":{"kind":"hypnotic_gaze","rangeFeet":5,"save":{"ability":"wisdom","dc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]}},"conditions":["charmed","incapacitated","speed_zero"],"extensionEconomy":"action","targetImmunityUntil":"long_rest"}}},{"id":"enchantment-hypnotic-gaze-action","type":"action","sourceKey":"wizard:enchantment:hypnotic-gaze","key":"wizard_enchantment_hypnotic_gaze","label":"Гипнотический взгляд","economy":"action","range":{"kind":"ranged","normal":5,"unit":"ft"},"effects":[{"kind":"semantic","key":"hypnotic_gaze","payload":{"saveAbility":"wisdom","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]},{"id":"enchantment-hypnotic-gaze-extend","type":"action","sourceKey":"wizard:enchantment:hypnotic-gaze","key":"wizard_enchantment_extend_hypnotic_gaze","label":"Продлить Гипнотический взгляд","economy":"action","effects":[{"kind":"semantic","key":"extend_hypnotic_gaze","payload":{"until":"end_of_next_turn","adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"enchantment-instinctive-charm-rules","type":"grant","sourceKey":"wizard:enchantment:instinctive-charm","target":"feature","key":"subclass:wizard:enchantment:instinctive-charm","payload":{"label":"Инстинктивное очарование","description":"Когда видимый нападающий в 30 футах атакует вас и имеет другую допустимую цель, реакцией потребуйте спасбросок Мудрости. При провале он атакует ближайшую допустимую цель. Успех даёт этой цели иммунитет к способности до долгого отдыха; сцену и цели ведёт ГМ.","mechanic":{"kind":"instinctive_charm","rangeFeet":30,"save":{"ability":"wisdom","dc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]}},"redirectsAttack":true,"targetImmunityUntil":"long_rest"}}},{"id":"enchantment-instinctive-charm-action","type":"action","sourceKey":"wizard:enchantment:instinctive-charm","key":"wizard_enchantment_instinctive_charm","label":"Инстинктивное очарование","economy":"reaction","range":{"kind":"ranged","normal":30,"unit":"ft"},"effects":[{"kind":"semantic","key":"redirect_attack_to_nearest_valid_target","payload":{"saveAbility":"wisdom","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","reaction","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"enchantment-split-enchantment-rules","type":"grant","sourceKey":"wizard:enchantment:split-enchantment","target":"feature","key":"subclass:wizard:enchantment:split-enchantment","payload":{"label":"Раздельное очарование","description":"Когда заклинание Очарования 1 уровня или выше на выбранном уровне нацеливается только на одно существо, оно может одновременно выбрать вторую допустимую цель.","mechanic":{"kind":"split_enchantment","minimumSpellLevel":1,"originalTargetCount":1,"addedTargets":1}}}]'::jsonb, '[]'::jsonb,
    '[{"id":"enchantment-alter-memories-rules","type":"grant","sourceKey":"wizard:enchantment:alter-memories","target":"feature","key":"subclass:wizard:enchantment:alter-memories","payload":{"label":"Изменение воспоминаний","description":"Одну цель вашего Очарования можно оставить в неведении о магическом влиянии. Один раз до конца заклинания действием потребуйте спасбросок Интеллекта; при провале цель забывает до 1 + модификатор Харизмы часов очарования, минимум 1 и не больше фактической длительности. ГМ ведёт цель и окно применения.","mechanic":{"kind":"alter_memories","save":{"ability":"intelligence","dc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]}},"forgottenHours":"max(1, 1 + charisma_modifier)","oncePerEnchantingSpell":true}}},{"id":"enchantment-alter-memories-action","type":"action","sourceKey":"wizard:enchantment:alter-memories","key":"wizard_enchantment_alter_memories","label":"Изменить воспоминания","economy":"action","effects":[{"kind":"semantic","key":"alter_charmed_target_memories","payload":{"saveAbility":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb
  );

  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-conjuration', 'subclass:wizard:conjuration', 'Школа призыва',
    'Призыватель создаёт предметы, перемещает союзников и укрепляет вызванных существ.', 'Безопасное перемещение — конечный ресурс; восстановление от заклинания Призыва подтверждает ГМ, а положение и призванные существа остаются сценовыми.',
    'Player''s Handbook 2014', '2014-compatible-on-wizard-2024',
    '[{"id":"conjuration-legacy-savant-rules","type":"grant","sourceKey":"wizard:conjuration:savant","target":"feature","key":"subclass:wizard:conjuration:savant","payload":{"label":"Знаток Призыва","description":"Время и золото, необходимые для переписывания заклинания школы Призыва в книгу заклинаний, уменьшаются вдвое. Эту транзакцию подтверждает ГМ.","mechanic":{"kind":"wizard_legacy_school_savant","school":"conjuration","copyTimeMultiplier":0.5,"copyGoldMultiplier":0.5}}},{"id":"conjuration-minor-conjuration-rules","type":"grant","sourceKey":"wizard:conjuration:minor-conjuration","target":"feature","key":"subclass:wizard:conjuration:minor-conjuration","payload":{"label":"Малое призывание","description":"Действием создайте в руке или свободном пространстве в 10 футах виденный ранее немагический неодушевлённый предмет: до 3 футов по стороне, до 10 фунтов. Он светится на 5 футов и исчезает через час, при уроне или повторном использовании.","mechanic":{"kind":"minor_conjuration","rangeFeet":10,"maximumCubeFeet":3,"maximumWeightPounds":10,"duration":"1_hour"}}},{"id":"conjuration-minor-conjuration-action","type":"action","sourceKey":"wizard:conjuration:minor-conjuration","key":"wizard_conjuration_minor_conjuration","label":"Малое призывание","economy":"action","effects":[{"kind":"semantic","key":"create_minor_conjured_object","payload":{"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"conjuration-benign-transposition-resource","type":"resource","sourceKey":"wizard:conjuration:benign-transposition","key":"wizard_conjuration_benign_transposition","label":"Безопасное перемещение","max":1,"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"conjuration-benign-transposition-rules","type":"grant","sourceKey":"wizard:conjuration:benign-transposition","target":"feature","key":"subclass:wizard:conjuration:benign-transposition","payload":{"label":"Безопасное перемещение","description":"Действием телепортируйтесь в видимое свободное пространство в 30 футах либо поменяйтесь местами с согласным Маленьким или Средним существом. Одно применение восстанавливается после долгого отдыха или немедленно после заклинания Призыва 1 уровня или выше; этот триггер подтверждает ГМ.","mechanic":{"kind":"benign_transposition","resource":"wizard_conjuration_benign_transposition","rangeFeet":30,"restoreOnConjurationSpellMinLevel":1}}},{"id":"conjuration-benign-transposition-action","type":"action","sourceKey":"wizard:conjuration:benign-transposition","key":"wizard_conjuration_benign_transposition","label":"Безопасное перемещение","economy":"action","resourceCosts":[{"key":"wizard_conjuration_benign_transposition","amount":1}],"effects":[{"kind":"semantic","key":"teleport_or_swap","payload":{"rangeFeet":30,"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]},{"id":"conjuration-benign-transposition-restore","type":"action","sourceKey":"wizard:conjuration:benign-transposition","key":"wizard_conjuration_restore_benign_transposition","label":"Восстановить Безопасное перемещение","economy":"special","effects":[{"kind":"resource","key":"wizard_conjuration_benign_transposition","operation":"RESTORE","amount":1}],"tags":["wizard","subclass","gm-adjudicated-trigger","conjuration-spell-cast"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"conjuration-focused-conjuration-rules","type":"grant","sourceKey":"wizard:conjuration:focused-conjuration","target":"feature","key":"subclass:wizard:conjuration:focused-conjuration","payload":{"label":"Сосредоточенное призывание","description":"Полученный урон не может прервать вашу концентрацию на заклинании школы Призыва; остальные причины потери концентрации действуют обычно.","mechanic":{"kind":"concentration_protection","school":"conjuration","ignoresDamageChecks":true}}}]'::jsonb, '[]'::jsonb,
