    'Некромант извлекает жизнь из убийств заклинаниями и усиливает созданную нежить.', 'Трупы, убийства, лечение и подконтрольная нежить остаются каноническими решениями ГМ; постоянные сопротивления попадают в CE.',
    'Player''s Handbook 2014', '2014-compatible-on-wizard-2024',
    '[{"id":"necromancy-legacy-savant-rules","type":"grant","sourceKey":"wizard:necromancy:savant","target":"feature","key":"subclass:wizard:necromancy:savant","payload":{"label":"Знаток Некромантии","description":"Время и золото, необходимые для переписывания заклинания школы Некромантии в книгу заклинаний, уменьшаются вдвое. Эту транзакцию подтверждает ГМ.","mechanic":{"kind":"wizard_legacy_school_savant","school":"necromancy","copyTimeMultiplier":0.5,"copyGoldMultiplier":0.5}}},{"id":"necromancy-grim-harvest-rules","type":"grant","sourceKey":"wizard:necromancy:grim-harvest","target":"feature","key":"subclass:wizard:necromancy:grim-harvest","payload":{"label":"Мрачная жатва","description":"Один раз в ход, убив существо заклинанием 1 уровня или выше, восстановите HP: удвоенный уровень ячейки, либо утроенный для Некромантии. Конструкты и нежить не подходят. Убийство, ход и изменение HP подтверждает ГМ.","mechanic":{"kind":"grim_harvest","healingPerSlotLevel":2,"necromancyHealingPerSlotLevel":3,"minimumSpellLevel":1,"excludes":["construct","undead"],"cadence":"once_per_turn","adjudicatedBy":"gm"}}}]'::jsonb, '[]'::jsonb,
    '[{"id":"necromancy-undead-thralls-rules","type":"grant","sourceKey":"wizard:necromancy:undead-thralls","target":"feature","key":"subclass:wizard:necromancy:undead-thralls","payload":{"label":"Неживые рабы","description":"Добавьте Оживление мёртвых в книгу заклинаний, если его там нет. Каждое сотворение создаёт или возвращает под контроль дополнительную нежить; созданная вами нежить получает к максимуму HP ваш уровень Волшебника и добавляет бонус мастерства к урону оружием.","mechanic":{"kind":"undead_thralls","grantsSpellbookSpell":"animate-dead","additionalCorpsePerCast":1,"summonedMaxHpBonus":"wizard_level","weaponDamageBonus":"proficiency_bonus","adjudicatedBy":"gm"}}},{"id":"necromancy-animate-dead-access","type":"spell","sourceKey":"wizard:necromancy:undead-thralls","key":"spell:animate-dead","catalogSlug":"animate-dead","variantKey":"wizard:necromancy:undead-thralls:animate-dead","payload":{"spell":{"name":"Оживление мёртвых","level":3,"school":"necromancy"},"preparation":{"mode":"prepared"},"methods":[{"key":"slot","kind":"class_spell","ability":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"attackBonus":{"kind":"add","terms":[{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"requiresPrepared":false,"resourceOptions":[{"key":"slot-3","castLevel":3,"label":"Ячейка 3 уровня","costs":[{"key":"spell_slot_3","amount":1}]},{"key":"slot-4","castLevel":4,"label":"Ячейка 4 уровня","costs":[{"key":"spell_slot_4","amount":1}]},{"key":"slot-5","castLevel":5,"label":"Ячейка 5 уровня","costs":[{"key":"spell_slot_5","amount":1}]},{"key":"slot-6","castLevel":6,"label":"Ячейка 6 уровня","costs":[{"key":"spell_slot_6","amount":1}]},{"key":"slot-7","castLevel":7,"label":"Ячейка 7 уровня","costs":[{"key":"spell_slot_7","amount":1}]},{"key":"slot-8","castLevel":8,"label":"Ячейка 8 уровня","costs":[{"key":"spell_slot_8","amount":1}]},{"key":"slot-9","castLevel":9,"label":"Ячейка 9 уровня","costs":[{"key":"spell_slot_9","amount":1}]}]}]}}]'::jsonb, '[]'::jsonb,
    '[{"id":"necromancy-inured-to-undeath-rules","type":"grant","sourceKey":"wizard:necromancy:inured-to-undeath","target":"feature","key":"subclass:wizard:necromancy:inured-to-undeath","payload":{"label":"Привычка к нежити","description":"Вы получаете сопротивление некротическому урону, а максимум HP не может быть уменьшен.","mechanic":{"kind":"inured_to_undeath","necroticResistance":true,"maximumHitPointsCannotBeReduced":true}}},{"id":"necromancy-necrotic-resistance","type":"grant","sourceKey":"wizard:necromancy:inured-to-undeath","target":"resistance","key":"damage:necrotic","payload":{"label":"Сопротивление некротическому урону"}}]'::jsonb, '[]'::jsonb,
    '[{"id":"necromancy-command-undead-rules","type":"grant","sourceKey":"wizard:necromancy:command-undead","target":"feature","key":"subclass:wizard:necromancy:command-undead","payload":{"label":"Подчинение нежити","description":"Действием выберите видимую нежить в 60 футах. При провале спасброска Харизмы она подчиняется вам; одновременно можно удерживать одну цель. Интеллект цели меняет повторные спасброски и иммунитет. Цель и длительный контроль ведёт ГМ.","mechanic":{"kind":"command_undead","rangeFeet":60,"save":{"ability":"charisma","dc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]}},"maximumControlled":1,"adjudicatedBy":"gm"}}},{"id":"necromancy-command-undead-action","type":"action","sourceKey":"wizard:necromancy:command-undead","key":"wizard_necromancy_command_undead","label":"Подчинить нежить","economy":"action","range":{"kind":"ranged","normal":60,"unit":"ft"},"effects":[{"kind":"semantic","key":"command_undead","payload":{"saveAbility":"charisma","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb
