    'Player''s Handbook 2014', '2014-compatible-on-wizard-2024',
    '[{"id":"transmutation-legacy-savant-rules","type":"grant","sourceKey":"wizard:transmutation:savant","target":"feature","key":"subclass:wizard:transmutation:savant","payload":{"label":"Знаток Преобразования","description":"Время и золото, необходимые для переписывания заклинания школы Преобразования в книгу заклинаний, уменьшаются вдвое. Эту транзакцию подтверждает ГМ.","mechanic":{"kind":"wizard_legacy_school_savant","school":"transmutation","copyTimeMultiplier":0.5,"copyGoldMultiplier":0.5}}},{"id":"transmutation-minor-alchemy-rules","type":"grant","sourceKey":"wizard:transmutation:minor-alchemy","target":"feature","key":"subclass:wizard:transmutation:minor-alchemy","payload":{"label":"Малая алхимия","description":"За 10 минут на кубический фут временно преобразуйте дерево, камень, железо, медь или серебро в другой материал из этого списка. Эффект требует концентрации и длится до часа.","mechanic":{"kind":"minor_alchemy","minutesPerCubicFoot":10,"duration":"1_hour","concentration":true,"materials":["wood","stone","iron","copper","silver"]}}},{"id":"transmutation-minor-alchemy-action","type":"action","sourceKey":"wizard:transmutation:minor-alchemy","key":"wizard_transmutation_minor_alchemy","label":"Начать Малую алхимию","economy":"special","effects":[{"kind":"semantic","key":"minor_alchemy","payload":{"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
