    '[{"id":"transmutation-shapechanger-resource","type":"resource","sourceKey":"wizard:transmutation:shapechanger","key":"wizard_transmutation_shapechanger","label":"Свободное превращение","max":1,"recharge":["short_rest","long_rest"],"restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"transmutation-shapechanger-rules","type":"grant","sourceKey":"wizard:transmutation:shapechanger","target":"feature","key":"subclass:wizard:transmutation:shapechanger","payload":{"label":"Изменяющий облик","description":"Добавьте Превращение в книгу заклинаний, если его там нет. Один раз до короткого или долгого отдыха наложите его на себя без ячейки, превращаясь в зверя с ПО не выше 1.","mechanic":{"kind":"shapechanger","grantsSpellbookSpell":"polymorph","resource":"wizard_transmutation_shapechanger","freeSelfCastMaximumCr":1}}},{"id":"transmutation-polymorph-access","type":"spell","sourceKey":"wizard:transmutation:shapechanger","key":"spell:polymorph","catalogSlug":"polymorph","variantKey":"wizard:transmutation:shapechanger:polymorph","payload":{"spell":{"name":"Превращение","level":4,"school":"transmutation"},"preparation":{"mode":"prepared"},"methods":[{"key":"slot","kind":"class_spell","ability":"intelligence","saveDc":{"kind":"add","terms":[{"kind":"literal","value":8},{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"attackBonus":{"kind":"add","terms":[{"kind":"reference","key":"core.proficiencyBonus"},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"requiresPrepared":false,"resourceOptions":[{"key":"slot-4","castLevel":4,"label":"Ячейка 4 уровня","costs":[{"key":"spell_slot_4","amount":1}]},{"key":"slot-5","castLevel":5,"label":"Ячейка 5 уровня","costs":[{"key":"spell_slot_5","amount":1}]},{"key":"slot-6","castLevel":6,"label":"Ячейка 6 уровня","costs":[{"key":"spell_slot_6","amount":1}]},{"key":"slot-7","castLevel":7,"label":"Ячейка 7 уровня","costs":[{"key":"spell_slot_7","amount":1}]},{"key":"slot-8","castLevel":8,"label":"Ячейка 8 уровня","costs":[{"key":"spell_slot_8","amount":1}]},{"key":"slot-9","castLevel":9,"label":"Ячейка 9 уровня","costs":[{"key":"spell_slot_9","amount":1}]}]}]}},{"id":"transmutation-shapechanger-action","type":"action","sourceKey":"wizard:transmutation:shapechanger","key":"wizard_transmutation_shapechanger","label":"Свободное превращение","economy":"action","resourceCosts":[{"key":"wizard_transmutation_shapechanger","amount":1}],"effects":[{"kind":"semantic","key":"cast_class_spell_without_slot","payload":{"spell":"polymorph","target":"self","maximumBeastCr":1,"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
    '[{"id":"transmutation-master-transmuter-rules","type":"grant","sourceKey":"wizard:transmutation:master-transmuter","target":"feature","key":"subclass:wizard:transmutation:master-transmuter","payload":{"label":"Мастер преобразования","description":"Действием уничтожьте свой Камень преобразователя ради одного эффекта: крупное превращение предмета, Панацея, возвращение к жизни либо омоложение. Новый камень нельзя создать до долгого отдыха; существование камня, цель и результат ведёт ГМ.","mechanic":{"kind":"master_transmuter","consumesTransmutersStone":true,"options":["major_transformation","panacea","restore_life","restore_youth"],"stoneRecreationAfter":"long_rest","adjudicatedBy":"gm"}}},{"id":"transmutation-master-major_transformation","type":"action","sourceKey":"wizard:transmutation:master-transmuter","key":"wizard_transmutation_master_major_transformation","label":"Мастер преобразования: major_transformation","economy":"action","effects":[{"kind":"semantic","key":"consume_transmuters_stone","payload":{"mode":"major_transformation","adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]},{"id":"transmutation-master-panacea","type":"action","sourceKey":"wizard:transmutation:master-transmuter","key":"wizard_transmutation_master_panacea","label":"Мастер преобразования: panacea","economy":"action","effects":[{"kind":"semantic","key":"consume_transmuters_stone","payload":{"mode":"panacea","adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]},{"id":"transmutation-master-restore_life","type":"action","sourceKey":"wizard:transmutation:master-transmuter","key":"wizard_transmutation_master_restore_life","label":"Мастер преобразования: restore_life","economy":"action","effects":[{"kind":"semantic","key":"consume_transmuters_stone","payload":{"mode":"restore_life","adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]},{"id":"transmutation-master-restore_youth","type":"action","sourceKey":"wizard:trans