  );

  perform private.upsert_wizard_subclass_runtime_v3(
    p_campaign_id, v_wizard,
    'wizard-war-magic', 'subclass:wizard:war-magic', 'Военная магия',
    'Военный маг быстрее вступает в бой, отклоняет атаки и накапливает силовые выбросы от разрушения чар.', 'Инициатива вычисляется CE; Силовые выбросы хранятся точно и после долгого отдыха устанавливаются в 1, а не заполняются.',
    'Xanathar''s Guide to Everything', '2014-compatible-on-wizard-2024',
    '[{"id":"war-magic-arcane-deflection-rules","type":"grant","sourceKey":"wizard:war-magic:arcane-deflection","target":"feature","key":"subclass:wizard:war-magic:arcane-deflection","payload":{"label":"Тайное отклонение","description":"Реакцией после попадания или проваленного спасброска получите +2 КД против этой атаки либо +4 к этому спасброску. До конца следующего хода после этого можно творить только заговоры. Момент и временное ограничение ведёт ГМ.","mechanic":{"kind":"arcane_deflection","armorClassBonus":2,"savingThrowBonus":4,"spellRestrictionUntilEndOfNextTurn":"cantrips_only","adjudicatedBy":"gm"}}},{"id":"war-magic-arcane-deflection-ac","type":"action","sourceKey":"wizard:war-magic:arcane-deflection","key":"wizard_war_magic_arcane_deflection_ac","label":"Тайное отклонение: +2 КД","economy":"reaction","effects":[{"kind":"semantic","key":"arcane_deflection","payload":{"mode":"armor_class","bonus":2,"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","reaction","gm-adjudicated-trigger"]},{"id":"war-magic-arcane-deflection-save","type":"action","sourceKey":"wizard:war-magic:arcane-deflection","key":"wizard_war_magic_arcane_deflection_save","label":"Тайное отклонение: +4 к спасброску","economy":"reaction","effects":[{"kind":"semantic","key":"arcane_deflection","payload":{"mode":"saving_throw","bonus":4,"adjudicatedBy":"gm"}}],"tags":["wizard","subclass","reaction","gm-adjudicated-trigger"]},{"id":"war-magic-tactical-wit-rules","type":"grant","sourceKey":"wizard:war-magic:initiative","target":"feature","key":"subclass:wizard:war-magic:tactical-wit","payload":{"label":"Тактическая смекалка","description":"Добавляйте модификатор Интеллекта к инициативе. Формула применяется автоматически.","mechanic":{"kind":"initiative_formula","formula":"dexterity_modifier + intelligence_modifier"}}},{"id":"war-magic-initiative-formula","type":"formula","sourceKey":"wizard:war-magic:initiative","label":"Тактическая смекалка","target":"combat.initiative","operation":"SET_FORMULA","formula":{"kind":"add","terms":[{"kind":"reference","key":"abilities.dexterity.modifier"},{"kind":"reference","key":"abilities.intelligence.modifier"}]}}]'::jsonb, '[]'::jsonb,
    '[{"id":"war-magic-power-surge-resource","type":"resource","sourceKey":"wizard:war-magic:power-surge","key":"wizard_war_magic_power_surge","label":"Силовые выбросы","max":{"kind":"max","values":[{"kind":"literal","value":1},{"kind":"reference","key":"abilities.intelligence.modifier"}]},"recharge":"long_rest","restore":"set","restoreAmount":1,"initial":1,"presentation":{"tone":"violet","display":"pips"}},{"id":"war-magic-power-surge-rules","type":"grant","sourceKey":"wizard:war-magic:power-surge","target":"feature","key":"subclass:wizard:war-magic:power-surge","payload":{"label":"Силовой выброс","description":"Максимум выбросов равен модификатору Интеллекта, минимум 1. После долгого отдыха запас становится ровно 1. Успешное Контрзаклинание или Рассеивание магии добавляет 1 до максимума. Один раз в ход при уроне заклинанием потратьте 1, чтобы нанести одной цели дополнительный силовой урон, равный половине уровня Волшебника.","mechanic":{"kind":"power_surge","resource":"wizard_war_magic_power_surge","maximum":"max(1, intelligence_modifier)","longRestValue":1,"gainOnSuccessfulSpellBreak":1,"damage":"floor(wizard_level / 2)","cadence":"once_per_turn"}}},{"id":"war-magic-power-surge-gain","type":"action","sourceKey":"wizard:war-magic:power-surge","key":"wizard_war_magic_gain_power_surge","label":"Получить Силовой выброс","economy":"special","effects":[{"kind":"resource","key":"wizard_war_magic_power_surge","operation":"RESTORE","amount":1}],"tags":["wizard","subclass","gm-adjudicated-trigger","successful-spell-break"]},{"id":"war-magic-power-surge-spend","type":"action","sourceKey":"wizard:war-magic:power-surge","key":"wizard_war_magic_spend_power_surge","label":"Потратить Силовой выброс","economy":"special","resourceCosts":[{"key":"wizard_war_magic_power_surge","amount":1}],"effects":[{"kind":"semantic","key":"power_surge_damage","payload":{"damageType":"force","amount":"floor(wizard_level / 2)","adjudicatedBy":"gm"}}],"tags":["wizard","subclass","gm-adjudicated-trigger"]}]'::jsonb, '[]'::jsonb,
