    '[{"id":"scribes-manifest-free-resource","type":"resource","sourceKey":"wizard:scribes:manifest-mind","key":"wizard_scribes_manifest_mind_free","label":"Свободное проявление разума","max":1,"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"scribes-manifest-casts-resource","type":"resource","sourceKey":"wizard:scribes:manifest-mind","key":"wizard_scribes_manifest_mind_casts","label":"Сотворения через разум","max":{"kind":"reference","key":"core.proficiencyBonus"},"recharge":"long_rest","restore":"full","initial":"full","presentation":{"tone":"violet","display":"pips"}},{"id":"scribes-manifest-mind-rules","type":"grant","sourceKey":"wizard:scribes:manifest-mind","target":"feature","key":"subclass:wizard:order-of-scribes:manifest-mind","payload":{"label":"Проявление разума","description":"Бонусным действием проявите разум книги в 60 футах бесплатно один раз до долгого отдыха; последующие проявления требуют любую ячейку. Пока он в 300 футах, через него можно сотворять заклинания Волшебника бонус мастерства раз до долгого отдыха. Положение и существование ведёт ГМ.","mechanic":{"kind":"manifest_mind","freeResource":"wizard_scribes_manifest_mind_free","originCastResource":"wizard_scribes_manifest_mind_casts","manifestRangeFeet":60,"maximumDistanceFeet":300}}},{"id":"scribes-manifest-mind-action","type":"action","sourceKey":"wizard:scribes:manifest-mind","key":"wizard_scribes_manifest_mind","label":"Проявить разум книги","economy":"bonus_action","costOptions":[{"key":"free","label":"Свободное проявление","costs":[{"key":"wizard_scribes_manifest_mind_free","amount":1}]},{"key":"slot-1","castLevel":1,"label":"Ячейка 1 уровня","costs":[{"key":"spell_slot_1","amount":1}]},{"key":"slot-2","castLevel":2,"label":"Ячейка 2 уровня","costs":[{"key":"spell_slot_2","amount":1}]},{"key":"slot-3","castLevel":3,"label":"Ячейка 3 уровня","costs":[{"key":"spell_slot_3","amount":1}]},{"key":"slot-4","castLevel":4,"label":"